    score = recall - 0.25 * fp
    if verdict is not None:
        want = "request-changes" if total else "approve"
        if verdict != want:
            score = min(score, 0.5)
    print(f"planted={total} matched={len(matched)} false_positives={fp}" + (f" verdict={verdict}" if verdict else ""))
    finish(score)


